-- === Lookup indices (built ONCE at load) =====================================
-- Entries are keyed by Twitch login/id. Two consumers:
--   * chat/mob path -> by_twitch_id (HOT: many calls per frame). O(1) hash.
--   * sub/gift + recocard author -> by_author (COLD: a few calls). Tiered match.
--
-- Normalization: strip to [a-z0-9] and lowercase. Twitch logins are already
-- [a-z0-9_], so normalizing drops the underscore too, letting a typed author
-- like "some_user" or "Some User" match the login "someuser".
local function normalize(s)
    return (string.gsub(string.lower(s), "[^%w]", ""))
end

local by_id = {}            -- twitch_id (string) -> user
local by_login = {}         -- exact lowercase login -> user
local by_login_norm = {}    -- normalized login -> user (first wins on collision)
for _, u in ipairs(USERS) do
    by_id[u.twitch_id] = u
    if u.login ~= nil then
        local lower = string.lower(u.login)
        by_login[lower] = u
        local norm = normalize(u.login)
        if by_login_norm[norm] == nil then by_login_norm[norm] = u end
    end
end

local M = {}

-- Look up a user by numeric Twitch id (chat/mob path). O(1); no fuzzy tiers --
-- ids are exact. This is the hot path, kept to a single hash lookup.
function M.by_twitch_id(twitch_id)
    if twitch_id == nil then return nil end
    return by_id[tostring(twitch_id)]
end

-- Look up a user by Twitch login. Case-insensitive exact match (O(1)).
function M.by_login(login)
    if login == nil then return nil end
    return by_login[string.lower(login)]
end

-- Look up a loadout for a free-text author / WizeBot celebrant name. Cold path
-- (sub/gift + recocard spawn), so it can afford fallback tiers. Stops at the
-- first tier that yields a match; returns nil if none:
--   1. case-insensitive exact login        (by_login)      O(1)
--   2. normalized exact login               (by_login_norm) O(1)
--   3. containment: a login whose normalized form CONTAINS the normalized input
--      (e.g. typed "CantTouchDis" -> login "canttouchdisnow"). O(n) scan,
--      returns the first such login. A wrong match here is harmless -- the user
--      still gets a valid cosmetic loadout -- so we do our best with whatever
--      was typed.
function M.by_author(author)
    if author == nil or author == "" then return nil end

    -- Tier 1: case-insensitive exact.
    local hit = by_login[string.lower(author)]
    if hit ~= nil then return hit end

    -- Tier 2: normalized exact.
    local norm = normalize(author)
    if norm == "" then return nil end
    hit = by_login_norm[norm]
    if hit ~= nil then return hit end

    -- Tier 3: containment scan. Returns the first login whose normalized form
    -- contains the typed name.
    for login_norm, u in pairs(by_login_norm) do
        if string.find(login_norm, norm, 1, true) then
            return u
        end
    end

    return nil
end

-- Full list, if a caller wants to iterate all users.
function M.all()
    return USERS
end

return M
